// This file is generated by AI.

// 参考音频裁剪对话框。
//
// 音频**过长**时弹出: 展示波形, 自动放置建议的裁剪区间, 允许拖拽调整与试听,
// 由后端执行实际裁剪 (后端同时负责 3~10 秒约束的最终校验)。
// 音频**过短**时不弹此对话框, 由后端静默补尾 —— 本组件在那种情况下只做提示。

import {
  Button,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  Dropdown,
  Input,
  Option,
} from '@fluentui/react-components';
import { PlayRegular, StopRegular } from '@fluentui/react-icons';
import { useEffect, useMemo, useRef, useState } from 'react';

import { voiceReadAudio, voiceWaveform, type Waveform } from '../commands/voice';
import { LANGUAGE_LABELS, MAX_REF_SECONDS, MIN_REF_SECONDS } from './types';

interface Props {
  path: string;
  /** 自动建议区间的起点 (秒); `suggestedEnd < 0` 表示无需裁剪 */
  suggestedStart: number;
  suggestedEnd: number;
  text: string;
  language: string;
  requireText: boolean;
  busy: boolean;
  error: string | null;
  onTextChange: (text: string) => void;
  onLanguageChange: (language: string) => void;
  onCancel: () => void;
  onConfirm: (start: number, end: number) => void;
}

const HEIGHT = 96;
const HANDLE_HIT = 8;

export function TrimDialog({
  path,
  suggestedStart,
  suggestedEnd,
  text,
  language,
  requireText,
  busy,
  error,
  onTextChange,
  onLanguageChange,
  onCancel,
  onConfirm,
}: Props) {
  const needsTrim = suggestedEnd >= 0;
  const [waveform, setWaveform] = useState<Waveform | null>(null);
  const [start, setStart] = useState(suggestedStart);
  const [end, setEnd] = useState(needsTrim ? suggestedEnd : 0);
  const [playing, setPlaying] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const dragRef = useRef<'start' | 'end' | null>(null);

  useEffect(() => {
    let disposed = false;
    void (async () => {
      try {
        const data = await voiceWaveform(path);
        if (!disposed) {
          setWaveform(data);
          if (!needsTrim) setEnd(data.duration);
        }
      } catch {
        // 波形不可用时仍允许确认 (后端会重新探测)
      }
    })();
    return () => {
      disposed = true;
      audioRef.current?.pause();
    };
  }, [path]);

  const duration = waveform?.duration ?? Math.max(end, suggestedStart, 1);
  const shownStart = needsTrim ? start : 0;
  const shownEnd = needsTrim ? end : duration;
  const selected = Math.max(0, shownEnd - shownStart);

  const columns = waveform?.columns ?? 0;

  // 绘制波形与选区
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const context = canvas.getContext('2d');
    if (!context) return;

    const width = canvas.clientWidth || 640;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = width * dpr;
    canvas.height = HEIGHT * dpr;
    context.scale(dpr, dpr);
    context.clearRect(0, 0, width, HEIGHT);

    // 选区底色
    if (needsTrim) {
      const from = (shownStart / duration) * width;
      const to = (shownEnd / duration) * width;
      context.fillStyle = 'rgba(80, 160, 255, 0.14)';
      context.fillRect(from, 0, to - from, HEIGHT);
    }

    if (waveform && columns > 0) {
      const middle = HEIGHT / 2;
      context.strokeStyle = 'rgba(128, 128, 128, 0.85)';
      context.beginPath();
      for (let column = 0; column < columns; column++) {
        const x = (column / columns) * width;
        const min = waveform.mins[column] ?? 0;
        const max = waveform.maxs[column] ?? 0;
        context.moveTo(x, middle - max * (HEIGHT / 2 - 2));
        context.lineTo(x, middle - min * (HEIGHT / 2 - 2));
      }
      context.stroke();
    }

    // 裁剪手柄
    if (needsTrim) {
      context.fillStyle = 'rgba(0, 120, 212, 0.9)';
      for (const position of [shownStart, shownEnd]) {
        const x = (position / duration) * width;
        context.fillRect(x - 1, 0, 2, HEIGHT);
      }
    }
  }, [waveform, columns, shownStart, shownEnd, duration, needsTrim]);

  const positionFromEvent = (event: React.PointerEvent<HTMLCanvasElement>): number => {
    const rect = event.currentTarget.getBoundingClientRect();
    const ratio = (event.clientX - rect.left) / Math.max(1, rect.width);
    return Math.min(duration, Math.max(0, ratio * duration));
  };

  const onPointerDown = (event: React.PointerEvent<HTMLCanvasElement>) => {
    if (!needsTrim) return;
    const rect = event.currentTarget.getBoundingClientRect();
    const position = positionFromEvent(event);
    const startX = (start / duration) * rect.width;
    const endX = (end / duration) * rect.width;
    const localX = event.clientX - rect.left;
    dragRef.current =
      Math.abs(localX - startX) <= HANDLE_HIT && Math.abs(localX - startX) <= Math.abs(localX - endX)
        ? 'start'
        : Math.abs(localX - endX) <= HANDLE_HIT
          ? 'end'
          : localX < startX
            ? 'start'
            : 'end';
    applyDrag(position);
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const applyDrag = (position: number) => {
    if (dragRef.current === 'start') {
      setStart(Math.min(position, end - 0.1));
    } else if (dragRef.current === 'end') {
      setEnd(Math.max(position, start + 0.1));
    }
  };

  const onPointerMove = (event: React.PointerEvent<HTMLCanvasElement>) => {
    if (!dragRef.current) return;
    applyDrag(positionFromEvent(event));
  };

  const onPointerUp = (event: React.PointerEvent<HTMLCanvasElement>) => {
    dragRef.current = null;
    event.currentTarget.releasePointerCapture(event.pointerId);
  };

  const togglePlay = async () => {
    if (playing) {
      audioRef.current?.pause();
      setPlaying(false);
      return;
    }
    try {
      const dataUrl = await voiceReadAudio(path);
      const audio = new Audio(dataUrl);
      audio.currentTime = needsTrim ? shownStart : 0;
      audioRef.current = audio;
      const stopAt = needsTrim ? shownEnd : duration;
      const timer = setInterval(() => {
        if (audio.currentTime >= stopAt) {
          audio.pause();
          clearInterval(timer);
          setPlaying(false);
        }
      }, 40);
      audio.onended = () => {
        clearInterval(timer);
        setPlaying(false);
      };
      await audio.play();
      setPlaying(true);
    } catch {
      setPlaying(false);
    }
  };

  const overLimit = selected > MAX_REF_SECONDS + 1e-3;
  const tooShort = selected < MIN_REF_SECONDS;
  const canConfirm = !busy && !overLimit && (!requireText || text.trim().length > 0);

  const durationLabel = useMemo(() => {
    if (!needsTrim) {
      return `当前 ${duration.toFixed(2)}s，不足 ${MIN_REF_SECONDS}s 的部分会在尾部补静音`;
    }
    return `当前 ${selected.toFixed(2)}s（上限 ${MAX_REF_SECONDS}s）${tooShort ? '，不足部分会在尾部补静音' : ''}`;
  }, [needsTrim, duration, selected, tooShort]);

  return (
    <Dialog open onOpenChange={(_, data) => (!data.open ? onCancel() : undefined)}>
      <DialogSurface className="voice-dialog trim-dialog">
        <DialogTitle>{needsTrim ? '裁剪参考音频' : '添加参考音频'}</DialogTitle>
        <DialogBody>
          <DialogContent>
            <p className="voice-dialog-hint">
              GPT-SoVITS 要求参考音频时长在 {MIN_REF_SECONDS}~{MAX_REF_SECONDS} 秒之间。
              {needsTrim ? '已按静音边界自动放置裁剪区间，可拖拽两端微调。' : '该音频较短，会在尾部补静音。'}
            </p>

            <div className="trim-waveform">
              <canvas
                ref={canvasRef}
                style={{ height: HEIGHT }}
                onPointerDown={onPointerDown}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerUp}
                onPointerCancel={onPointerUp}
              />
            </div>

            <div className="trim-toolbar">
              <Button
                appearance="secondary"
                size="small"
                icon={playing ? <StopRegular /> : <PlayRegular />}
                onClick={() => void togglePlay()}
              >
                {playing ? '停止' : '试听'}
              </Button>
              <span className="trim-readout">{durationLabel}</span>
              {needsTrim && (
                <span className="trim-range">
                  {shownStart.toFixed(2)}s → {shownEnd.toFixed(2)}s
                </span>
              )}
            </div>

            <div className="voice-row">
              <label className="voice-field">
                <span className="voice-label">语言</span>
                <Dropdown
                  className="voice-control"
                  selectedOptions={[language]}
                  value={LANGUAGE_LABELS[language] ?? language}
                  onOptionSelect={(_, data) => onLanguageChange(data.optionValue ?? 'zh')}
                >
                  {Object.entries(LANGUAGE_LABELS).map(([code, label]) => (
                    <Option key={code} value={code} text={label}>
                      {label}
                    </Option>
                  ))}
                </Dropdown>
              </label>
            </div>

            <label className="voice-field">
              <span className="voice-label">
                参考文本
                <span className="voice-required">*</span>
                <span className="voice-label-note">必须与音频逐字一致</span>
              </span>
              <Input
                value={text}
                placeholder="例如：我有什么不对劲的地方吗？"
                onChange={(_, data) => onTextChange(data.value)}
              />
            </label>

            {error && <p className="voice-error">{error}</p>}
            {overLimit && <p className="voice-error">裁剪区间超过 {MAX_REF_SECONDS}s 上限</p>}
          </DialogContent>

          <DialogActions>
            <Button appearance="secondary" onClick={onCancel} disabled={busy}>
              取消
            </Button>
            <Button
              appearance="primary"
              disabled={!canConfirm}
              onClick={() => onConfirm(shownStart, needsTrim ? shownEnd : -1)}
            >
              {busy ? '处理中…' : '确认'}
            </Button>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  );
}
